<template>
  <section v-if="active && patientId" class="appointment-follow-up" :aria-label="t('title')">
    <header><h2 ref="heading" tabindex="-1">{{ t('title') }}</h2><p>{{ t('patient') }} #{{ patientId }}</p><button type="button" :disabled="flow.state.phase==='submitting'" @click="refresh">{{ t('refresh') }}</button></header>
    <p v-if="flow.state.readPhase==='loading'" role="status" aria-live="polite">{{ t('loading') }}</p>
    <p v-if="flow.state.readPhase==='unavailable'" role="alert">{{ t(flow.state.error) }}</p>
    <p v-if="(detail?.schemaStatus || flow.state.capabilities?.schemaStatus)==='REMINDER_EXTENSION_REQUIRED'" role="status" class="appointment-warning">{{ t('REMINDER_EXTENSION_REQUIRED') }}</p>
    <template v-if="!sourceId">
      <p v-if="flow.state.readPhase==='ready' && !flow.state.items.length">{{ t('empty') }}</p>
      <ul class="appointment-cards"><li v-for="row in flow.state.items" :key="`${row.sourceKind}:${row.sourceId}`"><p>{{ t(row.sourceKind) }} #{{ row.sourceId }} · {{ wall(row.startWall) }}</p><p>{{ t(row.nativeStatus) }} · {{ t(row.attendance) }}</p><button type="button" :disabled="flow.locked() || !!draft" @click="open(row,$event)">{{ t('open') }}</button></li></ul>
      <div class="appointment-actions"><button type="button" :disabled="flow.locked()" @click="flow.loadPage(false)">{{ t('first') }}</button><button v-if="flow.state.nextCursor" type="button" :disabled="flow.locked()" @click="flow.loadPage(true)">{{ t('next') }}</button></div>
    </template>
    <!-- 命令结果/原包恢复不依赖detail；读取失效不能隐藏已保存或未知结果。 -->
      <p v-if="flow.state.phase==='succeeded'" ref="outcomeHeading" tabindex="-1" role="status">{{ t('saved') }}<template v-if="flow.state.receipt"> {{ t(flow.state.receipt.sourceKind) }} #{{ flow.state.receipt.sourceId }} · v{{ flow.state.receipt.version }}</template></p>
      <p v-if="flow.state.phase==='submitting'" role="status" aria-live="polite">{{ t('submitting') }}</p>
      <section v-if="['unknown','conflict','invalid'].includes(flow.state.phase)" role="alert" class="appointment-warning">
        <p>{{ t(flow.state.phase) }}</p><p v-if="flow.state.error">{{ t(flow.state.error) }}</p>
        <div class="appointment-actions"><button v-if="flow.state.phase==='unknown'" type="button" @click="retry">{{ t('retry') }}</button><button type="button" @click="flow.compare">{{ t('compare') }}</button><button v-if="flow.state.phase!=='unknown'" type="button" :disabled="flow.state.phase==='conflict'&&!flow.state.compared" @click="flow.editAfterComparison">{{ t('editCompared') }}</button></div>
        <template v-if="flow.state.submitted"><h4>{{ t('submitted') }}</h4><dl><dt>{{ t(flow.state.submitted.operation) }}</dt><dd>v{{ flow.state.submitted.expectedVersion }} · #{{ flow.state.submitted.sourceId }}</dd><template v-for="(value,key) in submittedSummary" :key="key"><dt>{{ t(key) }}</dt><dd>{{ value }}</dd></template></dl></template>
        <p v-if="flow.state.compared && detail">{{ t('latest') }}: v{{ detail.version }} · {{ t(detail.nativeStatus) }} · {{ t(detail.attendance) }} · {{ wall(detail.startWall) }}</p>
      </section>
    <button v-if="flow.state.readPhase==='unavailable' && flow.hasSelection()" type="button" :disabled="flow.state.phase==='submitting'" @click="flow.reloadSelected">{{ t('reloadSource') }}</button>
    <article v-if="detail" class="appointment-detail">
      <h3 ref="detailHeading" tabindex="-1">{{ t(detail.sourceKind) }} #{{ detail.sourceId }}</h3>
      <p>{{ t('systemTime') }}</p><p>{{ wall(detail.startWall) }}<template v-if="detail.endWall"> – {{ wall(detail.endWall) }}</template></p>
      <p>{{ t(detail.nativeStatus) }} · {{ t(detail.attendance) }}</p><p v-if="detail.attendanceOrigin!=='UNKNOWN'">{{ t(detail.attendanceOrigin) }}</p>
      <p v-if="detail.actualTimeKind==='UNKNOWN'">{{ t('actualUnknown') }}</p><p v-else>{{ t('actual') }}: {{ detail.actualAtUtc }} UTC · {{ detail.actualOffset }}</p>
      <p v-if="detail.fact">{{ t('reportedBy') }}: {{ detail.fact.actor_name || `#${detail.fact.actor_id}` }} · {{ t('at') }} {{ detail.fact.recorded_at }}</p>
      <template v-if="detail.managed"><p>{{ t('owner') }}: {{ detail.responsibleName || detail.responsibleUserId }} (#{{ detail.responsibleUserId }}) · {{ t('ownerCurrent') }}: {{ t(detail.responsibleCurrent?'yes':'no') }}</p><p>{{ t('due') }}: {{ detail.dueAt }}</p><p>{{ t('nextDecision') }}: {{ t(detail.currentNextDecision) }}</p><p v-if="detail.successor">{{ t('successor') }}: {{ t(detail.successor.sourceKind) }} #{{ detail.successor.sourceId }} · {{ wall(detail.successor.startWall) }}</p></template>
      <section v-if="detail.reminder" class="appointment-reminder" :aria-label="t('reminder')"><h4>{{ t('reminder') }}</h4><p>{{ t(detail.reminder.status) }}</p><p v-if="detail.reminder.lastAttemptedAtUtc">{{ t('reminderAttemptedAt') }}: {{ detail.reminder.lastAttemptedAtUtc }}</p><p v-if="detail.reminder.nativeNotifiedWall">{{ t('reminderNativeMarker') }}: {{ wall(detail.reminder.nativeNotifiedWall) }}</p><p>{{ t('reminderNote') }}</p></section>
      <p v-if="!detail.allowedCommands?.length">{{ t('readOnly') }}</p>
      <div v-if="!flow.state.draft" class="appointment-actions"><button v-for="operation in detail.allowedCommands" :key="operation" type="button" :disabled="flow.locked()" @click="begin(operation,$event)">{{ t(operation) }}</button></div>
      <form v-if="draft" ref="form" class="appointment-form" @submit.prevent="submit">
        <h4 tabindex="-1" ref="formHeading">{{ t(flow.state.operation) }}</h4>
        <p v-if="formError" role="alert">{{ t(formError) }}</p>
        <fieldset :disabled="flow.locked() || ['conflict','invalid'].includes(flow.state.phase)">
          <template v-if="flow.state.operation==='TRACK_APPOINTMENT'"><p>{{ t('recurrence') }}</p><label class="appointment-check"><input v-model="draft.confirmTrack" type="checkbox" required /><span>{{ t('trackConfirm') }}</span></label></template>
          <div v-if="needsResponsibility" class="appointment-fields"><div><label>{{ t('owner') }}<select v-model="draft.responsibleUserId" required @change="rememberPerson('owner')"><option value="">{{ t('choose') }}</option><option v-if="draft.responsibleUserId && !flow.state.owners.some(row=>Number(row.userId)===Number(draft.responsibleUserId))" :value="draft.responsibleUserId">{{ draft.ownerChoiceName || t('selectedAccount') }} (#{{ draft.responsibleUserId }})</option><option v-for="row in flow.state.owners" :key="row.userId" :value="row.userId">{{ row.displayName }} (#{{ row.userId }})</option></select></label><p v-if="flow.state.ownerPhase==='unavailable'" role="alert">{{ t('pickerUnavailable') }}</p><p v-if="flow.state.ownerPhase==='ready' && !flow.state.owners.length">{{ t('emptyCandidatePage') }}</p><div class="appointment-actions"><button type="button" @click="flow.loadPeople('owner')">{{ t('first') }}</button><button v-if="flow.state.ownerCursor" type="button" @click="flow.loadPeople('owner',true)">{{ t('next') }}</button></div></div><label>{{ t('due') }}<input v-model="draft.dueAt" type="text" placeholder="2026-10-17T09:30:00.123456" autocomplete="off" required /></label></div>
          <label v-if="flow.state.operation==='SET_NEXT_DECISION'">{{ t('nextDecision') }}<select v-model="draft.nextDecision" required><option value="">{{ t('choose') }}</option><option v-for="value in ['NEEDS_DECISION','NOT_ARRANGED','CLOSED_UNRESOLVED']" :key="value" :value="value">{{ t(value) }}</option></select></label>
          <label v-if="flow.state.operation==='REPLACE_NEXT'">{{ t('nextMode') }}<select v-model="draft.nextMode" @change="loadCandidates"><option value="CREATE">{{ t('CREATE') }}</option><option value="LINK">{{ t('LINK') }}</option></select></label>
          <p v-if="flow.state.operation==='REPLACE_NEXT'">{{ t('keepPrevious') }}</p>
          <template v-if="needsSchedule"><p>{{ t('systemTime') }}</p><div class="appointment-fields"><label>{{ t('start') }}<input v-model="draft.startAt" type="datetime-local" step="1" required /></label><label v-if="detail.sourceKind==='CARE_ITEM_APPOINTMENT'">{{ t('notify') }}<input v-model="draft.notifyAt" type="datetime-local" step="1" /></label><template v-else><label>{{ t('end') }}<input v-model="draft.endAt" type="datetime-local" step="1" required /></label><div><label>{{ t('doctor') }}<select v-model="draft.doctorUserId" required @change="rememberPerson('doctor')"><option value="">{{ t('choose') }}</option><option v-if="draft.doctorUserId && !flow.state.doctors.some(row=>Number(row.userId)===Number(draft.doctorUserId))" :value="draft.doctorUserId">{{ draft.doctorChoiceName || t('selectedAccount') }} (#{{ draft.doctorUserId }})</option><option v-for="row in flow.state.doctors" :key="row.userId" :value="row.userId">{{ row.displayName }} (#{{ row.userId }})</option></select></label><p v-if="flow.state.doctorPhase==='unavailable'" role="alert">{{ t('pickerUnavailable') }}</p><p v-if="flow.state.doctorPhase==='ready' && !flow.state.doctors.length">{{ t('emptyCandidatePage') }}</p><div class="appointment-actions"><button type="button" @click="flow.loadPeople('doctor')">{{ t('first') }}</button><button v-if="flow.state.doctorCursor" type="button" @click="flow.loadPeople('doctor',true)">{{ t('next') }}</button></div><p>{{ t('slotRecheck') }}</p></div><label>{{ t('schedule') }}<input v-model="draft.scheduleId" inputmode="numeric" pattern="[1-9][0-9]*" /></label></template></div></template>
          <template v-if="needsTarget"><p v-if="flow.state.candidatePhase==='unavailable'" role="alert">{{ t('pickerUnavailable') }}</p><p v-if="flow.state.candidatePhase==='ready' && !flow.state.candidates.length">{{ t('emptyCandidatePage') }}</p><label>{{ t('target') }}<select v-model="draft.targetId" required @change="selectTarget"><option value="">{{ t('choose') }}</option><option v-for="row in flow.state.candidates" :key="row.sourceId" :value="row.sourceId">#{{ row.sourceId }} · {{ wall(row.startWall) }} · {{ t(row.nativeStatus) }}</option></select></label><div class="appointment-actions"><button type="button" @click="flow.loadCandidates(false)">{{ t('first') }}</button><button v-if="flow.state.candidateCursor" type="button" @click="flow.loadCandidates(true)">{{ t('next') }}</button></div><p v-if="flow.state.target">#{{ flow.state.target.sourceId }} · {{ wall(flow.state.target.startWall) }} · v{{ flow.state.target.version }}</p><label class="appointment-check"><input v-model="draft.confirmTarget" type="checkbox" required :disabled="!flow.state.target" /><span>{{ t('targetConfirm') }}</span></label></template>
          <template v-if="needsActual"><label v-if="flow.state.operation!=='COMPLETE_SELECTED_APPOINTMENT'">{{ t('attendance') }}<select v-model="draft.attendance" required><option value="">{{ t('choose') }}</option><option value="ATTENDED">{{ t('ATTENDED') }}</option><option value="NO_SHOW">{{ t('NO_SHOW') }}</option><option v-if="flow.state.operation==='CORRECT_ATTENDANCE'" value="UNVERIFIED">{{ t('UNVERIFIED') }}</option></select></label><label>{{ t('timeChoice') }}<select v-model="draft.timeKind" required><option value="">{{ t('choose') }}</option><option value="KNOWN">{{ t('KNOWN') }}</option><option value="UNKNOWN">{{ t('actualUnknown') }}</option></select></label><template v-if="draft.timeKind==='KNOWN'"><p>{{ t('actualHelp') }}</p><div class="appointment-fields"><label>{{ t('actualWall') }}<input v-model="draft.actualWall" placeholder="2026-10-17T09:30:00.123456" autocomplete="off" required /></label><label>{{ t('actualOffset') }}<input v-model="draft.actualOffset" placeholder="+08:00" autocomplete="off" required /></label></div></template><p v-if="draft.timeKind==='UNKNOWN'">{{ t('unknownHelp') }}</p></template>
          <label v-if="flow.state.operation==='CANCEL' && (detail.successor || detail.nextDecision==='SCHEDULED')">{{ t('successorDisposition') }}<select v-model="draft.successorDisposition" required><option value="">{{ t('choose') }}</option><option value="KEEP_LINK">{{ t('KEEP_LINK') }}</option><option value="UNLINK">{{ t('UNLINK') }}</option></select></label>
          <label v-if="needsReason">{{ t('reason') }}<textarea v-model="draft.reason" maxlength="500" rows="3" required /></label>
          <div class="appointment-actions"><button type="submit" class="appointment-primary">{{ t('save') }}</button><button type="button" @click="cancelDraft">{{ t('cancelDraft') }}</button></div>
        </fieldset>
      </form>
      <button type="button" :disabled="flow.state.phase==='submitting'" @click="flow.loadEvents(false)">{{ t('history') }}</button>
      <ol class="appointment-history"><li v-for="event in flow.state.events" :key="event.id"><p>{{ t(event.event_type) }} · {{ event.actor_name }} · {{ event.recorded_at }}</p><p v-if="event.reason">{{ event.reason }}</p></li></ol><button v-if="flow.state.eventCursor" type="button" @click="flow.loadEvents(true)">{{ t('next') }}</button>
    </article>
  </section>
</template>
<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { useVisitFollowUp } from '@/composables/useVisitFollowUp';
import { appointmentText as t } from '@/utils/visitFollowUpCopy';
import { appointmentBody } from '@/utils/appointmentFollowUpForms';
const props = defineProps({ patientId: [Number, String], sourceKind: String, sourceId: [Number, String], active: { type: Boolean, default: true } });
const emit = defineEmits(['changed', 'locked']);
const flow = useVisitFollowUp(computed(() => props.patientId)), heading = ref(null), detailHeading = ref(null), outcomeHeading = ref(null), formHeading = ref(null), form = ref(null), formError = ref(null);
const detail = computed(() => flow.state.detail), draft = computed(() => flow.state.draft);
let returnFocus = null;
const wall = value => String(value || '—').replace('T', ' ').replace(/\.000000$/, '');
const fieldWall = value => String(value || '').replace(' ', 'T').replace(/\.0{1,6}$/, '').replace(/Z$/, '');
const needsResponsibility = computed(() => ['TRACK_APPOINTMENT','SET_NEXT_DECISION','CREATE_NEXT','LINK_NEXT','REPLACE_NEXT'].includes(flow.state.operation));
const needsSchedule = computed(() => ['RESCHEDULE','CREATE_NEXT'].includes(flow.state.operation) || flow.state.operation === 'REPLACE_NEXT' && draft.value?.nextMode === 'CREATE');
const needsTarget = computed(() => flow.state.operation === 'LINK_NEXT' || flow.state.operation === 'REPLACE_NEXT' && draft.value?.nextMode === 'LINK');
const needsActual = computed(() => ['RECORD_ATTENDANCE','COMPLETE_SELECTED_APPOINTMENT','CORRECT_ATTENDANCE'].includes(flow.state.operation));
const needsReason = computed(() => !['TRACK_APPOINTMENT','COMPLETE_SELECTED_APPOINTMENT'].includes(flow.state.operation));
const submittedSummary = computed(() => { const body = flow.state.submitted?.body || {}, result = {}; if (body.reason) result.reason = body.reason; if (body.attendance) result.attendance = t(body.attendance); if (body.actual) result.actual = body.actual.timeKind === 'UNKNOWN' ? t('actualUnknown') : body.actual.occurredAt; if (body.responsibleUserId) result.owner = body.responsibleUserId; if (body.dueAt) result.due = body.dueAt; if (body.nextDecision) result.nextDecision = t(body.nextDecision); if (body.schedule) { result.start = body.schedule.eventAt || `${body.schedule.startAt} – ${body.schedule.endAt}`; if (body.schedule.doctorUserId) result.doctor = body.schedule.doctorUserId; if (body.schedule.scheduleId) result.schedule = body.schedule.scheduleId; if (body.schedule.notifyAt) result.notify = body.schedule.notifyAt; } if (body.successor) result.successor = `#${body.successor.sourceId} · v${body.successor.expectedVersion}`; return result; });
async function refresh() { if (!props.active || !props.patientId) return; if (props.sourceId) await flow.open(props.sourceKind, props.sourceId, flow.locked()); else if (flow.hasSelection()) await flow.reloadSelected(); else { await flow.loadCapabilities(); if (flow.state.capabilities?.appointments) await flow.loadPage(); } }
async function open(row, event) { returnFocus = event?.currentTarget; await flow.open(row.sourceKind, row.sourceId); await nextTick(); detailHeading.value?.focus(); }
async function begin(operation, event) {
  const current = detail.value, creating = ['CREATE_NEXT','REPLACE_NEXT'].includes(operation);
  if (!flow.begin(operation, { responsibleUserId: current.responsibleUserId || '', ownerChoiceName: current.responsibleName || '', doctorChoiceName: current.doctorName || '', dueAt: fieldWall(current.dueAt), nextDecision: '', startAt: creating ? '' : fieldWall(current.startWall), endAt: creating ? '' : fieldWall(current.endWall), notifyAt: creating ? '' : fieldWall(current.notifyWall), doctorUserId: current.doctorUserId || '', scheduleId: creating ? '' : current.scheduleId || '', attendance: '', timeKind: '', actualWall: '', actualOffset: '', reason: '', nextMode: 'CREATE', targetId: '', confirmTarget: false, confirmTrack: false, successorDisposition: '' })) return;
  returnFocus = event.currentTarget; formError.value = null; await Promise.all([needsResponsibility.value ? flow.loadPeople('owner') : null, needsSchedule.value && current.sourceKind==='CARE_APPOINTMENT' ? flow.loadPeople('doctor') : null, needsTarget.value ? flow.loadCandidates() : null]); await nextTick(); formHeading.value?.focus();
}
function rememberPerson(role) { const owner=role==='owner', id=owner?draft.value.responsibleUserId:draft.value.doctorUserId, row=(owner?flow.state.owners:flow.state.doctors).find(row=>Number(row.userId)===Number(id)); draft.value[owner?'ownerChoiceName':'doctorChoiceName']=row?.displayName || ''; }
async function submit() { formError.value = null; try { const body = appointmentBody(flow.state.operation, draft.value, detail.value, flow.state.target); const result = await flow.submit(body); if (result.phase === 'succeeded') { emit('changed'); await nextTick(); (outcomeHeading.value || detailHeading.value)?.focus(); } } catch (error) { formError.value = error.message; await nextTick(); formHeading.value?.focus(); } }
async function retry() { const result = await flow.retry(); if (result.phase === 'succeeded') { emit('changed'); await nextTick(); (outcomeHeading.value || detailHeading.value)?.focus(); } }
async function loadCandidates() { flow.state.target = null; draft.value.confirmTarget = false; draft.value.targetId = ''; if (needsTarget.value) await flow.loadCandidates(); }
async function selectTarget() { draft.value.confirmTarget = false; if (draft.value.targetId) await flow.selectTarget(draft.value.targetId); else flow.state.target = null; }
async function cancelDraft() { if (flow.cancelDraft()) { formError.value = null; await nextTick(); if (returnFocus?.isConnected) returnFocus.focus(); else detailHeading.value?.focus(); } }
watch(() => [props.patientId, props.sourceKind, props.sourceId, props.active], () => { if (!props.active) { if (!flow.locked() && !flow.state.draft) flow.clear(); } else refresh(); }, { immediate: true });
watch(() => flow.state.phase, () => emit('locked', flow.locked()));
function beforeUnload(event) { if (flow.locked()) { event.preventDefault(); event.returnValue = ''; } }
onMounted(() => window.addEventListener('beforeunload', beforeUnload));
onUnmounted(() => window.removeEventListener('beforeunload', beforeUnload));
// 未知结果与未保存草稿保留在原患者/来源，普通导航不能悄悄丢弃。
function protectContext(event) { if (flow.locked() || flow.state.draft) event.preventDefault(); }
onMounted(() => window.addEventListener('care-plan-before-context-change', protectContext));
onUnmounted(() => window.removeEventListener('care-plan-before-context-change', protectContext));
onBeforeRouteLeave(() => !flow.locked() && !flow.state.draft);
defineExpose({ openSource: row => open(row, null), locked: flow.locked, dirty: () => !!flow.state.draft, protectNavigation: () => !flow.locked() && !flow.state.draft, refresh });
</script>
<style scoped>
.appointment-follow-up{min-width:0;margin-block:1rem;padding:1rem;border:1px solid #cbd5e1;border-radius:12px;background:#fff;color:#172b3a;overflow-wrap:anywhere}.appointment-follow-up header,.appointment-actions{display:flex;align-items:center;flex-wrap:wrap;gap:.65rem}.appointment-follow-up h2,.appointment-follow-up h3{margin-block:.4rem}.appointment-follow-up header h2{flex:1 1 16rem}.appointment-follow-up button,.appointment-follow-up input,.appointment-follow-up select,.appointment-follow-up textarea{font:inherit;max-width:100%;box-sizing:border-box}.appointment-follow-up button{min-height:44px;padding:.6rem .85rem;white-space:normal;line-height:1.5;border:1px solid #728497;border-radius:8px;background:#f8fafc;color:#17344b;cursor:pointer}.appointment-follow-up button:disabled{opacity:.6;cursor:not-allowed}.appointment-follow-up :focus-visible{outline:3px solid #1767ad;outline-offset:3px}.appointment-cards{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:1rem}.appointment-cards li,.appointment-detail,.appointment-warning{padding:1rem;border:1px solid #cbd5e1;border-radius:8px;margin-block:.75rem}.appointment-warning{background:#fff8e6}.appointment-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:1rem}.appointment-form fieldset{border:0;padding:0;margin:0;min-width:0}.appointment-form label{display:flex;flex-direction:column;gap:.4rem;margin-block:.7rem;min-width:0}.appointment-form input,.appointment-form select,.appointment-form textarea{width:100%;min-height:44px;border:1px solid #728497;border-radius:6px;padding:.6rem;background:#fff;color:#172b3a}.appointment-form label.appointment-check{flex-direction:row;align-items:flex-start}.appointment-check input{width:24px;min-height:24px;flex:0 0 24px;margin-top:.2rem}.appointment-primary{min-height:48px!important;background:#174f76!important;color:#fff!important}.appointment-history{padding-inline-start:1.3rem}.appointment-warning dl{display:grid;grid-template-columns:minmax(6rem,1fr) minmax(0,2fr);gap:.5rem}.appointment-warning dd{margin:0}@media(max-width:480px){.appointment-follow-up{padding:.65rem}.appointment-detail{padding:.65rem}.appointment-actions>*{flex:1 1 100%}.appointment-warning dl{display:block}.appointment-warning dd{margin-block:.3rem .7rem}}
</style>
